head.script:
scwin.trigger1_onclick = function(e) {
    wc.createWindow("title1" + title, null, "http://ww2.test.com:8080/5.0_1.2475B.20170120.154256_1.5_without_testcase/websquare/websquare.html?w2xPath=/TEST/20170120rc/winc_crossdomain_WPF-1319_(WSQ-2369)_winc1.xml", 'test1', '11', '', 'tsClose');
    winc = Number(winc) + 1;
    title = Number(title) + 1;
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 2. windowContainer좌측 상단의 나란히보기 형식을 클릭하여 'test1'화면과 'test2'화면을 마우스로 클릭하여 포커스가 이동되는지 확인한다.
    //2. Click on the side view type in the upper left corner of windowContainer and check if the focus is moved by clicking mouse on 'test1' screen and 'test2' screen.
    //Verify step 2. The focus is moved.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wc_horizontal').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wc_nameLayer_'+$p.id+'wc_subWindow0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wc_subWindow0_header').hasClass('w2window_header w2window_selected_header')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wc_nameLayer_'+$p.id+'wc_subWindow1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wc_subWindow1_header').hasClass('w2window_header w2window_selected_header')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.winc = "1";
    window.title = "1";
    window.tsClose = function(e) {
        debugger;
        alert('gkgk');
    };
    wc.createWindow("title1" + title, null, "http://ww2.test.com:8080/5.0_1.2475B.20170120.154256_1.5_without_testcase/websquare/websquare.html?w2xPath=/TEST/20170120rc/winc_crossdomain_WPF-1319_(WSQ-2369)_winc1.xml", 'test1', '11', '', 'tsClose');
    wc.createWindow("title2" + title, null, "http://ww2.test.com:8080/5.0_1.2475B.20170120.154256_1.5_without_testcase/websquare/websquare.html?w2xPath=/TEST/20170120rc/winc_crossdomain_WPF-1319_(WSQ-2369)_winc1.xml", 'test2', '21', '', 'tsClose');
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 04-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
